"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["67249"],{45526(e){e.exports=JSON.parse('{"id":"FIN-1065","slug":"variable-costing","term":"Variable Costing","also_known_as":[],"difficulty":"Advanced","definition":"Variable costing is a method of calculating product costs that includes only variable manufacturing costs in the cost of each unit, treating fixed production overheads as an expense of the period in which they occur.","explanation":["Under variable costing, also called marginal or direct costing, a unit\'s cost includes direct materials, direct labour and variable overheads, but not fixed overheads. All fixed costs are charged against profit in full each period.","Using the same example as absorption costing, a factory makes 1,000 units with variable costs of 10 each and fixed overheads of 5,000, selling 800. Under variable costing, the 200 unsold units are valued at 10 each, or 2,000, and the full 5,000 of fixed overhead is expensed this period.","Variable costing makes the relationship between sales volume and profit clearer, because profit is not affected by changes in inventory levels. It supports contribution margin analysis, break-even analysis and short-term decisions, such as whether to accept a special order.","Variable costing is not allowed for external financial reporting under IFRS or US GAAP, which require absorption costing. Many companies therefore use variable costing for internal management reports and adjust to absorption costing for published accounts."],"note":"","total":1500,"prev":{"slug":"variable-cost","term":"Variable Cost"},"next":{"slug":"variable-rate","term":"Variable Rate"}}')}}]);